// Erlaubte Werte, müssen zum System-Prompt passen
const KATEGORIEN = ["Zugang", "Hardware", "Netzwerk", "Sonstiges", "unklar"];
const PRIORITAETEN = ["hoch", "normal"];
const PFLICHT = ["kategorie", "prioritaet", "begruendung"];

const roh = $input.first().json.content[0].text;
const ticket = $('Ticket anlegen').first().json;

// Stufe 1: ist es gültiges JSON?
let daten;
try {
  daten = JSON.parse(roh);
} catch (e) {
  return [{ json: { ok: false, stufe: 1, grund: "kein gueltiges JSON", roh } }];
}

// Stufe 2: Pflichtfelder vorhanden?
// Zuerst: Ist das Ergebnis überhaupt ein Objekt? JSON.parse("5") oder
// JSON.parse("null") sind gültiges JSON, aber kein Objekt mit Feldern.
if (typeof daten !== "object" || daten === null || Array.isArray(daten)) {
  return [{ json: { ok: false, stufe: 2, grund: "JSON ist kein Objekt", roh } }];
}
const fehlend = PFLICHT.filter(k => !(k in daten));
if (fehlend.length > 0) {
  return [{ json: { ok: false, stufe: 2, grund: "Pflichtfeld fehlt: " + fehlend.join(", "), roh } }];
}

// Stufe 3: Werte erlaubt?
if (!KATEGORIEN.includes(daten.kategorie)) {
  return [{ json: { ok: false, stufe: 3, grund: "kategorie nicht erlaubt", roh } }];
}
if (!PRIORITAETEN.includes(daten.prioritaet)) {
  return [{ json: { ok: false, stufe: 3, grund: "prioritaet nicht erlaubt", roh } }];
}
if (typeof daten.begruendung !== "string" || daten.begruendung.trim() === "") {
  return [{ json: { ok: false, stufe: 3, grund: "begruendung ist kein nicht-leerer Text", roh } }];
}

return [{ json: {
  ok: true,
  ticket_id: ticket.ticket_id,
  kategorie: daten.kategorie,
  prioritaet: daten.prioritaet,
  begruendung: daten.begruendung
} }];
